-- #175 판정 이의 (ADR-0093 decision 1 #173 items 1, 2, 5–8, 11–13 and 15, decision 3 '#176 정정
-- 대기', the owner's answers of 2026-11-02 and 2026-11-03; ADR-0104). Generated by `drizzle-kit
-- generate`, then hand-edited where marked: this header and the tail. The snapshot is as generated.
--
-- - market_disputes: one row per dispute a member submitted against a provisional result — the
--   judgement disputed (market and version, a composite foreign key to market_judgements), the
--   submitter, the 근거 링크 (1–5) and the reason (1–2,000), the status (pending, dismissed,
--   accepted, retracted: a varchar held by a CHECK, so #176 adds its own), the submission instant,
--   the decision (who, when, the reason 1–500: exactly for dismissed and accepted), the 철회's
--   instant (exactly for retracted), and when the retention emptied a closed account's links and
--   reason in place (`purged_at`; then '{}' and ''). One per member per version, a retracted one
--   included (the full unique key: '고칠 수는 없다', #173 item 6). The indexes: the holding disputes
--   of a version (pending or accepted — the hold the confirmation and the worker's scan read), the
--   pending queue oldest first, the decided list by its decision or retraction, and a member's own.
--   buddha_app has no DELETE, and a trigger refuses a DELETE whoever writes and lets an UPDATE only
--   decide or retract a pending dispute once, or empty a decided or retracted one once (below).
-- - markets.dispute_hold_count: how many of the current version's disputes hold the market
--   (pending or accepted), mirrored for the labels '이의 검토 중' and '판정 지연' (#173 items 11·12)
--   and written by the @buddha/db dispute writers under the market lock; never below 0, and 0 on a
--   market that is not PROVISIONAL. 0 on every existing row: no dispute existed before this
--   migration.
-- - retention_purges_kind_check: the purge records take the new kind `market_disputes` (#184's
--   RETENTION_PURGE_KINDS, ADR-0087 (6)) — the generated drop and add of the CHECK, the list as
--   before (0046's) with the kind after `link_flags`, where a run takes it.
-- - No new type, event type, approval kind or release setting: the admin action types
--   (`market_dispute_dismiss`, `market_dispute_accept`) are varchar values (@buddha/shared).
CREATE TABLE "market_disputes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"market_id" uuid NOT NULL,
	"judgement_version" integer NOT NULL,
	"user_id" text NOT NULL,
	"links" text[] NOT NULL,
	"reason" text NOT NULL,
	"status" varchar(20) DEFAULT 'pending' NOT NULL,
	"submitted_at" timestamp (3) with time zone NOT NULL,
	"decided_by" text,
	"decided_at" timestamp (3) with time zone,
	"decision_reason" text,
	"retracted_at" timestamp (3) with time zone,
	"purged_at" timestamp (3) with time zone,
	CONSTRAINT "market_disputes_market_id_judgement_version_user_id_unique" UNIQUE("market_id","judgement_version","user_id"),
	CONSTRAINT "market_disputes_status_check" CHECK ("market_disputes"."status" IN ('pending', 'dismissed', 'accepted', 'retracted')),
	CONSTRAINT "market_disputes_links_check" CHECK (("market_disputes"."purged_at" IS NULL AND array_ndims("market_disputes"."links") = 1 AND cardinality("market_disputes"."links") BETWEEN 1 AND 5 AND array_position("market_disputes"."links", NULL) IS NULL) OR ("market_disputes"."purged_at" IS NOT NULL AND "market_disputes"."links" = '{}')),
	CONSTRAINT "market_disputes_reason_check" CHECK (("market_disputes"."purged_at" IS NULL AND btrim("market_disputes"."reason") <> '' AND char_length("market_disputes"."reason") <= 2000) OR ("market_disputes"."purged_at" IS NOT NULL AND "market_disputes"."reason" = '')),
	CONSTRAINT "market_disputes_decision_check" CHECK (("market_disputes"."status" IN ('dismissed', 'accepted')) = ("market_disputes"."decided_by" IS NOT NULL) AND ("market_disputes"."status" IN ('dismissed', 'accepted')) = ("market_disputes"."decided_at" IS NOT NULL) AND ("market_disputes"."status" IN ('dismissed', 'accepted')) = ("market_disputes"."decision_reason" IS NOT NULL) AND ("market_disputes"."decision_reason" IS NULL OR (btrim("market_disputes"."decision_reason") <> '' AND char_length("market_disputes"."decision_reason") <= 500)) AND ("market_disputes"."decided_at" IS NULL OR "market_disputes"."decided_at" >= "market_disputes"."submitted_at")),
	CONSTRAINT "market_disputes_retracted_check" CHECK (("market_disputes"."status" = 'retracted') = ("market_disputes"."retracted_at" IS NOT NULL) AND ("market_disputes"."retracted_at" IS NULL OR "market_disputes"."retracted_at" >= "market_disputes"."submitted_at")),
	CONSTRAINT "market_disputes_purged_check" CHECK ("market_disputes"."purged_at" IS NULL OR ("market_disputes"."status" <> 'pending' AND "market_disputes"."purged_at" >= coalesce("market_disputes"."decided_at", "market_disputes"."retracted_at")))
);
--> statement-breakpoint
