-- Hand-edited: a dispute is a permanent fact (N04 §5), never removed — #24 publishes the count and
-- the statuses (#173 item 13), and the retention empties a closed account's in place instead
-- (`purged_at`). buddha_app keeps SELECT, INSERT and UPDATE of the default privileges in
-- docker/postgres/init/01-roles.sql (a decision, a retraction and the emptying are UPDATEs) and
-- loses DELETE.
REVOKE DELETE ON TABLE "market_disputes" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: nor does any other role (the migration role, a script) delete one or rewrite what it
-- recorded. An UPDATE either (a) takes a pending dispute to dismissed, accepted or retracted —
-- once: a dispute no longer pending takes no other move until #176 adds its own — with what the
-- submission recorded (the id, the judgement, the submitter, the links, the reason and the
-- submission instant) unchanged, the CHECKs holding the decision's or the retraction's columns;
-- or (b) is the retention's: `purged_at` from null to a value, the links and the reason emptied
-- ('{}', ''), every other column as it was — once, and only of a decided or retracted dispute
-- (market_disputes_purged_check). Nothing else changes a row. TRUNCATE fires no row trigger: the
-- wipe (wipe.ts) still empties the table. market_disputes has no generated column, so a BEFORE
-- row trigger costs its UPDATEs no stronger lock (0044's note).
CREATE FUNCTION market_disputes_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dispute % of market % is a permanent record and takes no DELETE', OLD.id,
      OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.purged_at IS NULL AND NEW.purged_at IS NOT NULL THEN
    IF NEW.links <> '{}' OR NEW.reason <> ''
       OR (NEW.id, NEW.market_id, NEW.judgement_version, NEW.user_id, NEW.status,
           NEW.submitted_at, NEW.decided_by, NEW.decided_at, NEW.decision_reason,
           NEW.retracted_at)
          IS DISTINCT FROM
          (OLD.id, OLD.market_id, OLD.judgement_version, OLD.user_id, OLD.status,
           OLD.submitted_at, OLD.decided_by, OLD.decided_at, OLD.decision_reason,
           OLD.retracted_at) THEN
      RAISE EXCEPTION 'dispute % of market % is emptied by its retention alone: its links and its reason, nothing else',
        OLD.id, OLD.market_id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status <> 'pending' OR NEW.status NOT IN ('dismissed', 'accepted', 'retracted')
     OR NEW.purged_at IS DISTINCT FROM OLD.purged_at THEN
    RAISE EXCEPTION 'dispute % of market % changes once, from pending to dismissed, accepted or retracted',
      OLD.id, OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.market_id, NEW.judgement_version, NEW.user_id, NEW.links, NEW.reason,
      NEW.submitted_at)
     IS DISTINCT FROM
     (OLD.id, OLD.market_id, OLD.judgement_version, OLD.user_id, OLD.links, OLD.reason,
      OLD.submitted_at) THEN
    RAISE EXCEPTION 'dispute % of market % keeps what its submission recorded', OLD.id,
      OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_disputes_keep_record
  BEFORE UPDATE OR DELETE ON "market_disputes"
  FOR EACH ROW EXECUTE FUNCTION market_disputes_keep_record();
